#!/usr/bin/env python3
import html,json,pathlib
from build import ROOT
CASES=[('ss03','Mixed-case tag text','[DEBUG] [Debug] [debug] [FIXme]'),('ss07','Relax repeated greater-than context','>> >>> >>= a>>b a>>>b'),('ss08','Additional reverse / double-headed arrows','-<< ->> <<- =>> =<< <<='),('ss09','Alternative not-equal form','~= ~=='),('ss10','Approximate / regex comparisons','=~ !~'),('ss11','Additional equal / punctuation operators','&&= ||= //= /= ?= ??='),('cv63','Arrow-style <=','<= >='),('cv64','Horizontal-bar comparisons','<= >='),('cv66','Alternative pipe arrows','|> <| ||> <||'),('ss01','Deliberately break multiple-equals ligatures','== === ===='),('ss02','Deliberately break comparison ligatures','!= !== <= >='),('ss04','Deliberately break underscore ligatures','__ ___ ____'),('ss05','Restore ordinary escape backslash',r'\n \t \u1234 \\')]
def main():
 out=ROOT/'specimens/code-features';(out/'fonts').mkdir(parents=True,exist_ok=True);link=out/'fonts/Small.woff2'
 if not link.exists():link.symlink_to('../../../code-features/MorimoCodeSmall-Regular.woff2')
 s='''<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Morimo Small optional programming features</title><style>@font-face{font-family:Small;src:url('fonts/Small.woff2')}*{box-sizing:border-box}body{background:#faf8f2;color:#263b30;margin:0;font:15px/1.65 system-ui}main{max-width:1320px;margin:auto;padding:24px 36px}h1{font-size:26px;font-weight:550}h2{font-size:16px;font-weight:550;margin:0}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.cell{min-width:0}.row{border-top:1px solid #cdd8cc;padding:12px 0}pre{font:400 23px/1.55 Small;font-synthesis:none;overflow:auto;margin:5px 0;color:#213b2c;white-space:pre}small{color:#526b58}details{margin-top:18px}summary{cursor:pointer}.normal{font-size:20px}p{margin:8px 0}@media(max-width:760px){main{padding:18px}.grid{display:block}pre{font-size:19px}}</style><main><h1>コード用：標準表示を保ち、任意の表現を追加</h1><p>同じSmall540/1080、ドット付き0、現在の字形。Maple由来の32機能を保持し、追加の表現はアプリから選べる状態にしています。下の右列だけ指定機能をON。</p><small>通常のcaltは両列で有効。機能の総数やGSUB処理数は「リガチャの個数」ではありません。</small><div class="grid"><p>指定機能 OFF / 現在の標準</p><p>指定機能 ON</p></div>'''
 for tag,label,text in CASES:
  if tag=='ss01':s+='<details><summary>リガチャを意図的に分断する選択肢・バックスラッシュ</summary>'
  s+='<section class="row" data-tag="'+tag+'"><h2>'+html.escape(tag+' · '+label)+'</h2><div class="grid"><div class="cell"><pre style="font-feature-settings:\''+tag+'\' 0">'+html.escape(text)+'</pre></div><div class="cell"><pre style="font-feature-settings:\''+tag+'\' 1">'+html.escape(text)+'</pre></div></div></section>'
 s+='</details><h2>標準のまま：文字・アクセント・日本語</h2><pre class="normal">0O 1lI 1001 0xFF · Árvíztűrő ŵŷ Nguyễn\nΈΉΌΎΏ Καλημέρα ЁЙЇ · á ő x̂́ α̈ が パ\nif (value != null &amp;&amp; count &gt;= 0) return x =&gt; x === 0;</pre><p>コードの字幅・通常の文字・Nerdフォールバック・Kittyの23px行高を維持。任意機能を全て一括で有効にはしていません。</p><small>Regularのプログラミング用途に適用できる機能を対象。イタリック専用・分数・上付き/下付き等は今回の対象外。未知の任意文字列や全ての言語文法を検証済みとはしていません。</small></main></html>'
 (out/'index.html').write_text(s);(out/'cases.json').write_text(json.dumps(CASES,ensure_ascii=False,indent=2)+'\n');print('Actual feature preview page prepared')
if __name__=='__main__':main()
